import{_ as a,o as e,c as r,aj as o}from"./chunks/framework.Cn87zHeG.js";const c=JSON.parse('{"title":"网络与升级常见问题","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/network-ota.md","filePath":"faq/network-ota.md"}'),i={name:"faq/network-ota.md"};function n(d,t,h,s,p,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="网络配置与-ota" tabindex="-1">网络与升级常见问题 <a class="header-anchor" href="#网络配置与-ota" aria-label="Permalink to &quot;网络与升级常见问题 {#网络配置与-ota}&quot;">​</a></h1><p>本页回答网络连接、设备标识和固件升级中的常见问题。首次使用请查看<a href="./../getting-started/network-ota.html">网络配置与 OTA 使用说明</a>，按图文步骤完成操作。</p><h2 id="q12" tabindex="-1">Q12. 怎么打开机器人的网络配置工具？ <a class="header-anchor" href="#q12" aria-label="Permalink to &quot;Q12. 怎么打开机器人的网络配置工具？ {#q12}&quot;">​</a></h2><p>先连接机器人，再在浏览器访问 <strong>8080</strong> 端口：网线直连使用 <code>http://10.42.0.2:8080</code>，连接机器人热点使用 <code>http://192.168.60.1:8080</code>，同一局域网使用 <code>http://&lt;机器人IP&gt;:8080</code>。详细说明见<a href="./../getting-started/network-ota.html#connect">连接与访问</a>。</p><p><span id="wired-direct"></span><span id="wired-ubuntu"></span><span id="wired-windows"></span></p><p>网线已插好但页面打不开时，先核对电脑有线网卡设置：电脑使用 <code>10.42.0.1</code>、子网掩码 <code>255.255.255.0</code>，不要与机器人地址 <code>10.42.0.2</code> 重复。配置截图见<a href="./../getting-started/network-ota.html#wired-direct">网线直连设置</a>，可直接查看 <a href="./../getting-started/network-ota.html#wired-ubuntu">Ubuntu</a> 或 <a href="./../getting-started/network-ota.html#wired-windows">Windows</a> 步骤。</p><h2 id="q13" tabindex="-1">Q13. 机器人热点叫什么名字？有密码吗？ <a class="header-anchor" href="#q13" aria-label="Permalink to &quot;Q13. 机器人热点叫什么名字？有密码吗？ {#q13}&quot;">​</a></h2><p>默认名称形如 <code>H1_&lt;设备ID&gt;</code>，实际名称以「热点配置」页为准。热点默认开放、无密码；通过本工具连接带密码的 WiFi 后，热点密码同步为该 WiFi 的密码；通过本工具主动断开 WiFi 后，热点恢复为无密码。临时掉线不等于主动断开。</p><p>热点密码不支持在此页手动修改。热点信息的查看位置见<a href="./../getting-started/network-ota.html#hotspot">热点配置说明</a>。</p><h2 id="q14" tabindex="-1">Q14. 怎么给机器人连接 WiFi？ <a class="header-anchor" href="#q14" aria-label="Permalink to &quot;Q14. 怎么给机器人连接 WiFi？ {#q14}&quot;">​</a></h2><p>在「WiFi 配置」中选择目标网络并连接；列表中找不到时，可刷新扫描或使用「手动连接」。连接成功后，在「状态」页核对网络名称和 IP 地址。完整步骤见<a href="./../getting-started/network-ota.html#wifi-connect">连接 WiFi</a>。</p><p>切换 WiFi 后原网页打不开，可能是机器人的局域网 IP 已改变。请使用新地址访问，或通过网线直连、机器人热点重新打开工具。</p><h2 id="q15" tabindex="-1">Q15. 连过的 WiFi 怎么管理 / 断开？ <a class="header-anchor" href="#q15" aria-label="Permalink to &quot;Q15. 连过的 WiFi 怎么管理 / 断开？ {#q15}&quot;">​</a></h2><p>「WiFi 配置」→「已保存网络」可连接或删除保存的网络；「状态」页的 WiFi 卡片可断开当前连接。删除保存的网络后，下次连接需要重新配置。</p><p>断开正在用于访问网页的 WiFi 后，网页连接也会中断，可改用网线或机器人热点访问。按钮位置见<a href="./../getting-started/network-ota.html#wifi-manage">管理与断开 WiFi</a>。</p><h2 id="q16" tabindex="-1">Q16. “设备 ID”和“机器人 ID”有什么区别？ <a class="header-anchor" href="#q16" aria-label="Permalink to &quot;Q16. “设备 ID”和“机器人 ID”有什么区别？ {#q16}&quot;">​</a></h2><p><strong>设备 ID</strong> 由设备网卡地址生成，在工具中不可修改；<strong>机器人 ID</strong> 是用户可自定义的设备标识，在「机器人配置」页设置。修改机器人 ID 不会修改设备的出厂序列号。</p><p><span id="robot-config"></span></p><p>设置和备份方法见<a href="./../getting-started/network-ota.html#robot-id">机器人 ID 与配置导出</a>。导出的 JSON 包含基础配置，不包含 WiFi 密码或 ROS 2 通信中间件配置。</p><h2 id="q17" tabindex="-1">Q17. 怎么做固件 OTA 升级？ <a class="header-anchor" href="#q17" aria-label="Permalink to &quot;Q17. 怎么做固件 OTA 升级？ {#q17}&quot;">​</a></h2><p>整机软件在「OTA 升级」页使用厂商提供、与设备匹配的 <code>.img</code> 文件升级。<strong>上传完成只代表文件已传入机器人，还需要执行升级</strong>；升级期间保持供电，完成并重启后再次核对软件版本。</p><p>操作步骤见<a href="./../getting-started/network-ota.html#system-ota">整机 OTA 升级</a>。机械臂、夹爪和回充板使用各自的升级页面与配套固件，不与整机升级包混用。</p><h2 id="q18" tabindex="-1">Q18. 升级过程中刷新页面 / 换设备登录，会中断升级吗？ <a class="header-anchor" href="#q18" aria-label="Permalink to &quot;Q18. 升级过程中刷新页面 / 换设备登录，会中断升级吗？ {#q18}&quot;">​</a></h2><p>不会。升级在机器人侧独立执行，重新打开对应页面会恢复显示状态。「停止监控」只停止当前页面的日志刷新，不会取消升级。</p><p><strong>不要通过关闭网页、停止监控或断电来中断升级。</strong> 进度与结果的查看方法见<a href="./../getting-started/network-ota.html#upgrade-status">升级状态说明</a>。</p><h2 id="q19" tabindex="-1">Q19. 点了升级后一直没反应怎么办？ <a class="header-anchor" href="#q19" aria-label="Permalink to &quot;Q19. 点了升级后一直没反应怎么办？ {#q19}&quot;">​</a></h2><p>如果触发升级后 <strong>20 秒内没有任何状态反馈</strong>，工具会提示「触发升级后无任何反馈」并解除页面锁定。这个时间是启动反馈等待时间，<strong>不是整次升级的完成时限</strong>。</p><p>先核对页面和升级包是否匹配，保留提示与日志，再联系技术支持。已经出现升级进度时，应等待最终结果，不要反复点击升级或断电重启。</p><h2 id="status" tabindex="-1">在哪里查看机器人当前的固件版本？ <a class="header-anchor" href="#status" aria-label="Permalink to &quot;在哪里查看机器人当前的固件版本？ {#status}&quot;">​</a></h2><p>进入网络配置工具的「状态」→「机器人信息」→「软件版本」。机械臂电机、回充板的版本属于对应硬件固件，与整机软件版本分别管理。</p><p>页面位置见<a href="./../getting-started/network-ota.html#status">状态与版本查询</a>，当前最新版本见<a href="./../firmware.html">固件版本公告</a>。</p><h2 id="ros2-config" tabindex="-1">ROS 2 通信配置保存后，为什么与当前使用的值不同？ <a class="header-anchor" href="#ros2-config" aria-label="Permalink to &quot;ROS 2 通信配置保存后，为什么与当前使用的值不同？ {#ros2-config}&quot;">​</a></h2><p>「本次启动使用」是此次启动时使用的通信实现；「已保存配置」供下次启动使用，保存后需要重启机器人才能生效，页面不会自动重启。</p><p>日常使用保持默认 Zenoh 设置即可。配置含义与高级操作见<a href="./../getting-started/network-ota.html#ros2-config">查看 ROS 2 通信配置</a>。</p><h2 id="hardware-upgrade" tabindex="-1">机械臂、夹爪和回充板固件应该在哪个页面升级？ <a class="header-anchor" href="#hardware-upgrade" aria-label="Permalink to &quot;机械臂、夹爪和回充板固件应该在哪个页面升级？ {#hardware-upgrade}&quot;">​</a></h2><p>各类固件用于对应硬件，操作前先确认设备配置和升级包是否匹配。入口如下：</p><table tabindex="0"><thead><tr><th>硬件</th><th>使用说明</th></tr></thead><tbody><tr><td><span id="arm-upgrade"></span>机械臂电机</td><td><a href="./../getting-started/network-ota.html#arm-upgrade">机械臂电机固件升级</a></td></tr><tr><td><span id="gripper-upgrade"></span>自研夹爪</td><td><a href="./../getting-started/network-ota.html#gripper-upgrade">自研夹爪固件升级</a>，仅适用于配备自研夹爪的机器人</td></tr><tr><td><span id="mcu-upgrade"></span>回充板</td><td><a href="./../getting-started/network-ota.html#mcu-upgrade">回充板固件升级</a>，仅适用于配备回充板的机器人</td></tr></tbody></table><p>升级时不要同时启动其他类型的升级任务。文件要求和完整操作见<a href="./../getting-started/network-ota.html#hardware-upgrade">硬件固件升级说明</a>。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>完整图文操作见<a href="./../getting-started/network-ota.html">网络配置与 OTA 使用说明</a>。</p>',40)])])}const u=a(i,[["render",n]]);export{c as __pageData,u as default};
